  import os, time, threading
  import numpy as np

  _lock = threading.Lock()
  _model = None
  _disabled = False

  def _lazy_model():
      global _model, _disabled
      if _disabled:
          return None
      if _model is None:
          with _lock:
              if _model is None and not _disabled:
                  t0 = time.time()
                  try:
                      from sentence_transformers import SentenceTransformer
                      _model = SentenceTransformer(os.getenv("RERANK_MODEL","sentence-transformers/all-MiniLM-L6-v2"))
                      print(f"[reranker] model loaded in {time.time()-t0:.2f}s")
                  except Exception as e:
                      print(f"[reranker] disable due to load error: {e}")
                      _disabled = True
                      return None
      return _model

  def maybe_rerank(query, docs, top_k=50, final_k=8, timeout_ms=300):
      # docs: list of {id, title, text, url?}
      if os.getenv("ENABLE_RERANKER","0") != "1":
          return docs[:final_k]

      model = _lazy_model()
      if model is None:
          return docs[:final_k]

      try:
          start = time.time()
          pool = docs[:top_k]
          # Encode with a timebox
          # Encode query
          qv = model.encode([query], show_progress_bar=False, batch_size=1, convert_to_numpy=True, normalize_embeddings=True)
          # Encode docs
          dv = model.encode([d.get("text","") or d.get("snippet","") for d in pool],
                            show_progress_bar=False, batch_size=64, convert_to_numpy=True, normalize_embeddings=True)
          # Timeout check
          if (time.time() - start) * 1000 > timeout_ms:
              return docs[:final_k]
          sims = (dv @ qv[0])
          order = np.argsort(-sims)
          ranked = [pool[i] for i in order[:final_k]]
          return ranked
      except MemoryError:
          global _disabled
          _disabled = True
          print("[reranker] OOM encountered; permanently disabling reranker for this process")
          return docs[:final_k]
      except Exception as e:
          print(f"[reranker] error, falling back: {e}")
          return docs[:final_k]

