# Simple in-memory trace store
class TraceStore:
    def __init__(self):
        self._data: Dict[str, Dict[str, Any]] = {}
        self._ts: Dict[str, float] = {}

    def add(self, tid: str, trace: Dict[str, Any]):
        self._data[tid] = trace
        self._ts[tid] = time.time()

    def get(self, tid: str) -> Optional[Dict[str, Any]]:
        return self._data.get(tid)

    def evict_older_than(self, cutoff: float):
        to_del = [k for k, ts in self._ts.items() if ts < cutoff]
        for k in to_del:
            self._data.pop(k, None)
            self._ts.pop(k, None)

trace_store = TraceStore()

def trim_large(val: Any, max_bytes: int = TRACE_MAX_FIELD_BYTES) -> Any:
    if isinstance(val, str) and len(val.encode("utf-8", "ignore")) > max_bytes:
        return val[: max_bytes // 2] + "...[trimmed]"
    if isinstance(val, list):
        return [trim_large(v, max_bytes) for v in val]
    if isinstance(val, dict):
        return {k: trim_large(v, max_bytes) for k, v in val.items()}
    return val

