import os
import time
from typing import List, Tuple

_model = None
_RERANK_BATCH = int(os.getenv("RERANK_BATCH", "64"))

def _load_model():
    global _model
    if _model is None:
        from sentence_transformers import CrossEncoder
        _model = CrossEncoder("cross-encoder/ms-marco-MiniLM-L-6-v2")

def rerank(query: str, pool: List[Tuple[str, float]], final_k: int, timeout_ms: int = 250) -> List[Tuple[str, float]]:
    # pool: list of (doc_id, prior_score)
    start = time.time()
    try:
        _load_model()
    except Exception:
        # Model unavailable; return stable top-k from pool
        return pool[:final_k]

    def timed_out():
        return (time.time() - start) * 1000.0 > timeout_ms

    pairs = [(query, doc_id) for doc_id, _ in pool]
    scores = []
    i = 0
    while i < len(pairs):
        if timed_out():
            return pool[:final_k]
        batch = pairs[i : i + _RERANK_BATCH]
        try:
            bscores = _model.predict(batch)
        except RuntimeError as e:
            if "out of memory" in str(e).lower():
                # Back off to smaller effective batch for this iteration
                if len(batch) > 8:
                    batch = batch[:8]
                    bscores = _model.predict(batch)
                else:
                    return pool[:final_k]
            else:
                return pool[:final_k]
        scores.extend(bscores)
        i += len(batch)

    rescored = list(zip([d for d, _ in pool], scores))
    rescored.sort(key=lambda x: x[1], reverse=True)
    top_ids = set([d for d, _ in rescored[:final_k]])
    # Preserve rescored order for selected, then stable keep rest if fewer than k
    out = [(d, s) for d, s in rescored if d in top_ids]
    if len(out) < final_k:
        extras = [p for p in pool if p[0] not in top_ids][: final_k - len(out)]
        out.extend(extras)
    return out[:final_k]

